-- Wrath exposes named CVars, not arbitrary filesystem reads. The companion can
-- import every SET entry from Config.wtf; known live values override the snapshot.
local function collectSettings()
    local keys={"gxResolution","gxWindow","gxMaximize","gxVSync","gxRefresh","gxMultisample","gxApi","gxColorBits","gxDepthBits","gxFixLag","maxFPS","maxFPSBk","uiScale","useUiScale","locale","realmList","realmName","expansion","Sound_EnableAllSound","Sound_MasterVolume","Sound_MusicVolume","Sound_SFXVolume","Sound_AmbienceVolume","Sound_EnableMusic","Sound_EnableSoundWhenGameIsInBG","Sound_OutputDriverName","Sound_NumChannels","farclip","horizonFarclip","groundEffectDensity","groundEffectDist","environmentDetail","textureFilteringMode","baseMip","shadowLevel","shadowTextureSize","shadowQuality","particleDensity","projectedTextures","weatherDensity","waterDetail","watermaxlod","terrainMipLevel","terrainTextureLod","componentTextureLevel","spellEffectLevel","showfootprints","showfootprintparticles","cameraDistanceMax","cameraDistanceMaxFactor","cameraSmoothStyle","cameraYawMoveSpeed","cameraPitchMoveSpeed","mouseSpeed","screenshotFormat","screenshotQuality","timingMethod","processAffinityMask","gxCursor","autoLootDefault","autoSelfCast","UberTooltips","showTutorials","checkAddonVersion","scriptErrors","movie","readTOS","readEULA","readTerminationWithoutNotice","readScanning","installType","gxTripleBuffer"}
    local values={}
    for _,entry in ipairs(RealmDeskConfigSnapshot or {}) do
        if type(entry)=="table" and type(entry.name)=="string" then values[entry.name]=tostring(entry.value or "") end
    end
    for _,key in ipairs(keys) do if values[key]==nil then values[key]="" end end
    local rows={}
    for key,snapshot in pairs(values) do
        local lower=key:lower()
        if not lower:find("password",1,true) and not lower:find("token",1,true) and not lower:find("secret",1,true) and lower~="accountname" and lower~="accountlist" then
            local ok,value=pcall(GetCVar,key)
            value=ok and value or nil
            if value~=nil or snapshot~="" then rows[#rows+1]={name=key,value=tostring(value or snapshot):sub(1,200)} end
        end
    end
    table.sort(rows,function(a,b) return a.name:lower()<b.name:lower() end)
    while #rows>256 do table.remove(rows) end
    return rows
end
local function collectDiag()
    local version,build = GetBuildInfo()
    local _,_,home,world = GetNetStats()
    local gameHour,gameMinute=GetGameTime()
    return {
      settings=collectSettings(),version=tostring(version or ""),build=tostring(build or ""),locale=GetLocale() or "",
        clientTime=date("%Y-%m-%d %H:%M:%S"),fps=math.floor((GetFramerate() or 0)*10)/10,
        homePing=home or 0,worldPing=world or 0,
        resolution=GetCVar("gxResolution") or "",graphics=GetCVar("graphicsQuality") or "",
        realmName=GetRealmName() or "",clientZone=GetZoneText() or "",
        clientSubzone=GetSubZoneText() or "",
        gameTime=string.format("%02d:%02d",gameHour or 0,gameMinute or 0)
    }
end

