local function repaintList()
    local visible={}
    for _,x in ipairs(state.list) do
        if state.filter=="All" or state.filter==x.status then visible[#visible+1]=x end
    end
    state.visibleRows=visible
    qContent:SetHeight(math.max(1,#visible*52))
    countLabel:SetText((state.total or #visible).." tickets | Page "..(state.page+1).." | "..state.filter)
    for i,x in ipairs(listButtons) do
        local row=visible[i]
        if row then
            local marker = row.id==state.currentId and "> " or "  "
            x.text:SetText(marker.."#"..row.id.."  "..string.sub(row.title or "",1,25).."\n     "..row.status.."  -  "..row.player)
            x.button:Show()
        else x.button:Hide() end
    end
end
