local function section(id,heading,x,y,w,h)
    local c=skin(CreateFrame("Frame",nil,canvas),"surface")
    c.id=id;c:SetSize(w,h);c:SetPoint("TOPLEFT",canvas,"TOPLEFT",x,-y)
    c:EnableMouse(true);c:EnableMouseWheel(true)
    local function wheel(_,delta)
        local parent=c:GetParent()
        while parent do
            if parent.rdScrollArea then UI.scrollWheel(parent,delta);return end
            parent=parent:GetParent()
        end
    end
    c:SetScript("OnMouseWheel",wheel)
    local header=skin(CreateFrame("Frame",nil,c),"header")
    header:SetPoint("TOPLEFT",2,-2);header:SetPoint("TOPRIGHT",-2,-2);header:SetHeight(35)
    header:EnableMouseWheel(true);header:SetScript("OnMouseWheel",wheel)
    local name=label(header,heading,14);name:SetPoint("LEFT",12,0)
    c.rdHeading=name;c:Hide();UI.sections[id]=c
    return c
end
