local function scrollText(card,id,bottom)
    local scroll=makeScrollFrame(card)
    scroll:SetPoint("TOPLEFT",12,-44);scroll:SetPoint("BOTTOMRIGHT",-30,bottom or 48)
    local content=CreateFrame("Frame",nil,scroll);content:SetSize(240,100)
    scroll:SetScrollChild(content)
    local fs=label(content,"",11);fs:SetPoint("TOPLEFT");fs:SetWidth(240)
    local function fitText()
        local width=math.max(50,scroll:GetWidth());content:SetWidth(width);fs:SetWidth(width)
        content:SetHeight(math.max(1,fs:GetStringHeight()+12))
    end
    card:HookScript("OnSizeChanged",fitText)
    fs.Refresh=fitText
    UI.lines[id]=fs
    return fs
end
local function addDataText(card,id)
    if id~="overview" and id~="details" then return scrollText(card,id) end
    -- Short ticket facts and the complete description flow with the outer column.
    local content=CreateFrame("Frame",nil,card)
    content:SetPoint("TOPLEFT",card,"TOPLEFT",14,-46);content:SetPoint("TOPRIGHT",card,"TOPRIGHT",-14,-46)
    card.rdFlowContent=content
    local fs=label(content,"",12);fs:SetPoint("TOPLEFT");UI.lines[id]=fs
    fs.Refresh=function()
        fs:SetWidth(math.max(50,card:GetWidth()-28))
        content:SetHeight(math.max(1,fs:GetStringHeight()))
    end
    card:HookScript("OnSizeChanged",fs.Refresh)
    return fs
end
