local function fmt(v) return tostring(v==nil and "-" or v) end
local function updateTicket()
    local t=state.ticket
    if not t then
        for id,x in pairs(UI.lines) do x:SetText(id=="responses" and "" or "Select a ticket from the queue.") end
        return
    end
    state.currentId=t.id
    title:SetText("#"..t.id.." - "..string.sub(t.title or "",1,48))
    status:SetText(t.status.."   |   "..t.category.."   |   "..t.player.."   |   "..t.created)
    UI.lines.overview:SetText(t.body or "")
    UI.lines.details:SetText("Status:  "..t.status.."\nPriority:  "..t.priority..
        "\nAssigned:  "..(t.assigned~="" and t.assigned or "Unassigned")..
        "\nCategory:  "..t.category.."\nTicket ID:  "..t.id)
    UI.lines.account:SetText("Account:  "..fmt(t.accountName).."\nAccount ID:  "..fmt(t.accountId)..
        "\nCharacter:  "..fmt(t.player).."\nCharacter ID:  "..fmt(t.charId).."  |  Level: "..fmt(t.level)..
        "\nRealm:  "..fmt(t.realmName).."  ("..fmt(t.realmId)..")"..
        "\nClass ID:  "..fmt(t.classId).."  |  Race ID: "..fmt(t.raceId)..
        "\nOnline now: "..(t.online and "Yes" or "No").."\nAccount fields are server verified.")
    UI.lines.location:SetText("Map / region:  "..fmt(t.mapName).." ("..t.mapId..")"..
        "\nZone:  "..fmt(t.zoneName).." ("..t.zoneId..")"..
        "\nArea:  "..fmt(t.areaName).." ("..t.areaId..")"..
        "\nInstance:  "..fmt(t.instanceId).."\nX / Y / Z:  "..
        string.format("%.2f / %.2f / %.2f",t.x or 0,t.y or 0,t.z or 0)..
        "\nOrientation (server): "..fmt(t.o).."\nServer ping:  "..fmt(t.ping).." ms | Client FPS (unverified):  "..fmt(t.fps)..
        "\nClient:  "..fmt(t.version).."  build "..fmt(t.build)..
        "\nLocale:  "..fmt(t.locale).."  |  "..fmt(t.resolution)..
        "\nClient zone:  "..fmt(t.clientZone).." / "..fmt(t.clientSubzone)..
        "\nRealm game time: "..fmt(t.gameTime)..
        "  |  Local: "..fmt(t.clientTime))
    local notes={}
    for i=1,#state.notes do
        local n=state.notes[i]
        notes[#notes+1]="["..n.when.."] "..n.author..(n.visibility=="internal" and " (INTERNAL)" or "")..": "..n.body
    end
    UI.lines.responses:SetText(#notes==0 and "No responses yet. Public replies are visible to the player." or table.concat(notes,"\n\n"))
    local activities={}
    for i=1,#state.activity do
        local a=state.activity[i]
        activities[#activities+1]=a.when.."   "..a.actor..": "..a.action.." - "..a.detail
    end
    UI.lines.history:SetText(#activities==0 and "No administrator activity." or table.concat(activities,"\n\n"))
    local medias={}
    for i=1,#state.media do local m=state.media[i];medias[#medias+1]=m.mediaType.."  "..m.name.." ("..m.bytes.." bytes) "..(m.created or "")..(m.author and " / account "..m.author or "") end
    UI.lines.media:SetText(#medias==0 and "No attached files. Use RealmDesk Capture for media uploads." or table.concat(medias,"\n"))
    UI.lines.assignment:SetText("Assigned to: "..(t.assigned~="" and t.assigned or "Unassigned").."\nCurrent status: "..t.status)
    for _,fs in pairs(UI.lines) do if fs.Refresh then fs.Refresh() end end
    repaintList()
end
