-- Complete workspace interactions. Drafts stay in memory, never in saved variables.
state.drafts={}
local service=label(side,"Connecting to realm...",10,"sideText")
service:SetPoint("TOPLEFT",18,-184);service:SetWidth(140);service:SetHeight(60)
local heartbeat=CreateFrame("Frame",nil,main)
local elapsed=0
local pendingAge=0
local baseCall=call
call=function(name,...)
    if name~="Hello" and state.ready==false then
        UI.notice:SetText("RealmDesk server is unavailable or needs migration 002. Your drafts are retained.")
        return
    end
    baseCall(name,...)
end
function H.ServiceInfo(_,version,isGM,url,schema)
    state.admin=isGM and true or false
    state.ready=version==2 and schema>=2
    state.mediaURL=type(url)=="string" and url:match("^https://[^/]+$") and url or ""
    service:SetText(state.ready and ((isGM and "Staff Workspace" or "Player Portal").."\nServer Connected") or "Server Update Required\nProtocol 2 / schema 2")
    if state.ready then
        local notice=UI.notice:GetText() or ""
        if notice:find("server is unavailable",1,true) or notice:find("Waiting for the RealmDesk",1,true) then UI.notice:SetText("") end
        call("List")
    end
end
main:HookScript("OnShow",function() state.ready=false;elapsed=0;call("Hello") end)
heartbeat:SetScript("OnUpdate",function(_,dt)
    elapsed=elapsed+dt
    if elapsed>=15 then
        elapsed=0
        if state.ready then
            call("List")
            if state.currentId then
                local t=state.ticket or {}
                call("Open",state.currentId,t.notePage or 0,t.historyPage or 0,t.mediaPage or 0)
            end
        else
            service:SetText("Server Not Ready\nUI available; drafts safe")
            call("Hello")
        end
    end
    if state.pendingCreate or state.pendingNote then
        pendingAge=pendingAge+dt
        if pendingAge>20 then
            state.pendingCreate=nil;state.pendingNote=nil;pendingAge=0
            UI.notice:SetText("No save confirmation. Draft retained; refresh before retrying to avoid duplicates.")
        end
