        if n:find("shadow") or n:find("texture") or n:find("terrain") or n:find("water") or n:find("effect") or n:find("clip") or n:find("density") or n:find("mip") or n:find("particle") or n:find("weather") then return "Graphics" end
        if n:find("realm") or n=="locale" or n=="expansion" then return "Network" end
        if n:find("ui") or n:find("tooltip") or n:find("addon") or n:find("loot") or n:find("script") or n:find("mouse") then return "Interface" end
        return "Other"
    end
    local function tooltip(frame,title,text)
        if not GameTooltip then return end
        GameTooltip:SetOwner(frame,"ANCHOR_RIGHT");GameTooltip:SetText(title)
        GameTooltip:AddLine(text,0.85,0.88,0.94,true);GameTooltip:Show()
    end
    local function render()
        for _,row in ipairs(rows) do row:Hide() end
        local t=state.ticket or {};local y=0;local count=0
        local groups={}
