            local name=category(setting.name);groups[name]=groups[name] or {};groups[name][#groups[name]+1]=setting
        end
        local function line(title,value,help,heading)
            count=count+1
            local row=rows[count]
            if not row then
                row=CreateFrame("Frame",nil,content);row:EnableMouse(true)
                row.caption=label(row,"",10,"muted");row.value=label(row,"",11);rows[count]=row
            end
            local width=math.max(200,card:GetWidth()-50)
            row:ClearAllPoints();row:SetPoint("TOPLEFT",0,-y);row:SetWidth(width)
            row.caption:ClearAllPoints();row.value:ClearAllPoints()
            row.caption:SetPoint("TOPLEFT",0,-3);row.caption:SetWidth(width*(heading and 1 or 0.64))
            row.caption:SetFont(FONT,heading and 11 or 10);row.caption:SetText(title)
            row.caption:SetTextColor(rgb(theme()[heading and "accent" or "muted"]))
            row.value:SetPoint("TOPRIGHT",0,-3);row.value:SetJustifyH("RIGHT");row.value:SetWidth(width*0.33);row.value:SetText(value or "")
            row.value:SetTextColor(rgb(theme().text))
            local height=heading and 27 or math.max(22,row.caption:GetStringHeight()+7,row.value:GetStringHeight()+7)
            row:SetHeight(height)
            row:SetScript("OnEnter",function(self) tooltip(self,title,help) end)
            row:SetScript("OnLeave",function() if GameTooltip then GameTooltip:Hide() end end)
            row:Show();y=y+height
        end
        line("Client Snapshot","","Client-reported values captured when the ticket was submitted. These values are unverified.",true)
        line("Version",t.version or "--","Client version at submission.")
        line("Build / Locale",fmt(t.build).." / "..fmt(t.locale),"Client executable build and language locale.")
        line("FPS / Latency",fmt(t.fps).." / "..fmt(t.ping).." ms","Submitted frame rate and server-measured network latency.")
        if not t.settings or #t.settings==0 then
            line("No Saved Settings", "", "This ticket predates settings capture or the host has not applied migration 003. Import Config.wtf through the companion to include every readable SET entry.",true)
        end
        for _,name in ipairs({"Display","Graphics","Audio","Interface","Camera","Network","Other"}) do
            if groups[name] then
                line(name,"",categories[name],true)
                table.sort(groups[name],function(a,b) return a.name:lower()<b.name:lower() end)
                for _,setting in ipairs(groups[name]) do line(setting.name,setting.value,meaning[setting.name] or (categories[name].." Setting: "..setting.name..". No build-specific description is available.")) end
            end
        end
        content:SetSize(math.max(200,card:GetWidth()-50),math.max(1,y))
    end
    UI.exportDetails=UI.exportDetails or {}
    UI.exportDetails.session=function()
        local t=state.ticket or {};local groups={}
        local lines={"Session Diagnostics","Client Snapshot (Client-Reported)","Version: "..fmt(t.version),"Build: "..fmt(t.build),"Locale: "..fmt(t.locale),
            "FPS: "..fmt(t.fps),"Server Latency: "..fmt(t.ping).." ms","Captured: "..fmt(t.clientTime)}
        for _,setting in ipairs(t.settings or {}) do local name=category(setting.name);groups[name]=groups[name] or {};groups[name][#groups[name]+1]=setting end
        for _,name in ipairs({"Display","Graphics","Audio","Interface","Camera","Network","Other"}) do
            if groups[name] then
                lines[#lines+1]="\n"..name
                table.sort(groups[name],function(a,b) return a.name:lower()<b.name:lower() end)
                for _,setting in ipairs(groups[name]) do lines[#lines+1]=setting.name..": "..setting.value end
            end
        end
        return table.concat(lines,"\n")
    end
    UI.renderSettings=render
    card:HookScript("OnSizeChanged",render)
    local previous=H.TicketData
    H.TicketData=function(...) previous(...);render() end
end)()

