-- Persisted outer-window dimensions with responsive fixed-section reflow.
;(function()
    local pending=false
    local applying=false
    local function valid(value,fallback)
        local n=tonumber(value)
        return n and n==n and n>0 and n<100000 and n or fallback
    end
    pref.window=type(pref.window)=="table" and pref.window or {}
    local function limits()
        local scale=math.min(1,(UIParent:GetWidth()-30)/1000,(UIParent:GetHeight()-30)/620)
        scale=math.max(0.1,scale)
        main:SetScale(scale)
        local maxW=math.max(1000,(UIParent:GetWidth()-30)/scale)
        local maxH=math.max(620,(UIParent:GetHeight()-30)/scale)
        main:SetMinResize(1000,620);main:SetMaxResize(maxW,maxH)
        return maxW,maxH
    end
    local function reflow()
        if applying then return end
        applying=true
        layout(false)
        title:SetWidth(math.max(250,main:GetWidth()-(pref.collapsed and 0 or 183)-56))
        status:SetWidth(title:GetWidth())
        notice:SetWidth(math.max(200,main:GetWidth()-(pref.collapsed and 10 or 193)-100))
        form:SetScale(math.min(1,(main:GetHeight()-36)/710,(main:GetWidth()-40)/465))
        UI.presentation.repaint()
        UI.resizeCanvas()
        applying=false;pending=false
    end
    local function save()
        pref.window.width=math.floor(main:GetWidth()+0.5)
        pref.window.height=math.floor(main:GetHeight()+0.5)
    end
    local function restore()
        local maxW,maxH=limits()
        main:SetSize(math.max(1000,math.min(maxW,valid(pref.window.width,1280))),math.max(620,math.min(maxH,valid(pref.window.height,760))))
        reflow()
    end
    UI.resetWindow=function() pref.window={};restore();save() end
    main:SetResizable(true)
    main:HookScript("OnSizeChanged",function() if not applying then pending=true end end)
    main:SetScript("OnEvent",function() restore() end)
    local grip=makeButton(main,"Resize",70,18,function() end,"control")
    grip.rdWindowResize=true;grip:SetPoint("BOTTOMRIGHT",-10,4)
    grip:RegisterForDrag("LeftButton")
    local function finish()
        if not state.windowResizing then return end
        main:StopMovingOrSizing();state.windowResizing=false;reflow();save()
    end
    grip:SetScript("OnDragStart",function() state.windowResizing=true;main:StartSizing("BOTTOMRIGHT") end)
    grip:SetScript("OnDragStop",finish)
    main:HookScript("OnHide",finish)
    local ticker=CreateFrame("Frame",nil,main);local elapsed=0
    ticker:SetScript("OnUpdate",function(_,dt)
        elapsed=elapsed+dt
        if pending and elapsed>=0.05 then elapsed=0;reflow() end
    end)
    restore()
end)()

